PRAGMA foreign_keys=ON; CREATE TABLE t6(a INTEGER PRIMARY KEY, b, c, d, FOREIGN KEY(c, d) REFERENCES t6(a, b)); CREATE UNIQUE INDEX t6i ON t6(b, a); INSERT INTO t6 VALUES(NULL, 'a', 1, 'a'); INSERT INTO t6 VALUES(2, 'a', 2, 'a'); INSERT INTO t6 VALUES(NULL, 'a', 1, 'a'); INSERT INTO t6 VALUES(5, 'a', 2, 'a'); CREATE TABLE t6_log(seq INTEGER PRIMARY KEY, op TEXT, a INTEGER, c INTEGER, d TEXT); CREATE TRIGGER t6_log_insert AFTER INSERT ON t6 BEGIN INSERT INTO t6_log(op,a,c,d) VALUES('insert',NEW.a,NEW.c,NEW.d); END; CREATE TRIGGER t6_log_update AFTER UPDATE ON t6 BEGIN INSERT INTO t6_log(op,a,c,d) VALUES('update',NEW.a,NEW.c,NEW.d); END; CREATE TRIGGER t6_log_delete AFTER DELETE ON t6 BEGIN INSERT INTO t6_log(op,a,c,d) VALUES('delete',OLD.a,OLD.c,OLD.d); END;